package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.*;import com.makemytrip.makemytrip.repositories.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
@Service public class PricingEngine {
 private final FlightRepository flights;private final HotelRepository hotels;private final BookingRepository bookings;private final PriceHistoryRepository history;private final PricingRulesRepository rulesRepository;
 @Value("${pricing.holiday-multiplier:1.20}") private double holidayMultiplier;@Value("${pricing.demand-multiplier:1.10}") private double demandMultiplier;@Value("${pricing.availability-multiplier:1.15}") private double availabilityMultiplier;@Value("${pricing.lead-time-multiplier:1.10}") private double leadTimeMultiplier;@Value("${pricing.demand-bookings-threshold:10}") private long demandThreshold;@Value("${pricing.low-inventory-threshold:3}") private int lowInventoryThreshold;
 public PricingEngine(FlightRepository flights,HotelRepository hotels,BookingRepository bookings,PriceHistoryRepository history,PricingRulesRepository rulesRepository){this.flights=flights;this.hotels=hotels;this.bookings=bookings;this.history=history;this.rulesRepository=rulesRepository;}
 public PricingRules getRules(){return rulesRepository.findById("default").orElseGet(()->{PricingRules r=new PricingRules();r.setHolidayMultiplier(holidayMultiplier);r.setDemandMultiplier(demandMultiplier);r.setAvailabilityMultiplier(availabilityMultiplier);r.setLeadTimeMultiplier(leadTimeMultiplier);r.setDemandBookingsThreshold(demandThreshold);r.setLowInventoryThreshold(lowInventoryThreshold);return r;});}
 public PricingRules updateRules(PricingRules r){if(r.getHolidayMonth()<1||r.getHolidayMonth()>12||r.getDemandBookingsThreshold()<0||r.getLowInventoryThreshold()<0||r.getHolidayMultiplier()<1||r.getDemandMultiplier()<1||r.getAvailabilityMultiplier()<1||r.getLeadTimeMultiplier()<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid pricing rules");r.setId("default");return rulesRepository.save(r);}
 public PriceHistory currentFlight(String id){Flight f=flights.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Flight not found"));PricingRules r=getRules();List<String> reasons=new ArrayList<>();boolean holiday=LocalDate.now().getMonthValue()==r.getHolidayMonth();long demand=bookings.countByFlightIdAndBookingDateAfter(id,LocalDate.now().minusDays(30));long days=-1;try{LocalDate dep=LocalDate.parse(f.getDepartureTime().substring(0,10));if(!dep.isBefore(LocalDate.now()))days=ChronoUnit.DAYS.between(LocalDate.now(),dep);}catch(Exception ignored){}if(holiday)reasons.add("HOLIDAY_PERIOD");if(f.getAvailableSeats()<=r.getLowInventoryThreshold())reasons.add("LOW_AVAILABILITY");if(demand>=r.getDemandBookingsThreshold())reasons.add("HIGH_DEMAND");if(days>=0&&days<=2)reasons.add("CLOSE_TO_DEPARTURE");return store("FLIGHT",id,f.getPrice(),calculateMultiplier(holiday,demand,f.getAvailableSeats(),days,r),reasons);}
 public PriceHistory currentHotel(String id){Hotel h=hotels.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Hotel not found"));PricingRules r=getRules();List<String> reasons=new ArrayList<>();boolean holiday=LocalDate.now().getMonthValue()==r.getHolidayMonth();long demand=bookings.countByHotelIdAndBookingDateAfter(id,LocalDate.now().minusDays(30));if(holiday)reasons.add("HOLIDAY_PERIOD");if(h.getAvailableRooms()<=r.getLowInventoryThreshold())reasons.add("LOW_AVAILABILITY");if(demand>=r.getDemandBookingsThreshold())reasons.add("HIGH_DEMAND");return store("HOTEL",id,h.getPricePerNight(),calculateMultiplier(holiday,demand,h.getAvailableRooms(),-1,r),reasons);}
 public List<PriceHistory> history(String type,String id){return history.findByItemTypeAndItemIdOrderByTimestampDesc(type,id);}
 public double calculateMultiplier(boolean holiday,long recentBookings,int remainingInventory,long daysToTravel){double multiplier=1d;if(holiday)multiplier*=holidayMultiplier;if(remainingInventory<=lowInventoryThreshold)multiplier*=availabilityMultiplier;if(recentBookings>=demandThreshold)multiplier*=demandMultiplier;if(daysToTravel>=0&&daysToTravel<=2)multiplier*=leadTimeMultiplier;return multiplier;}
 private double calculateMultiplier(boolean holiday,long demand,int inventory,long days,PricingRules r){double multiplier=1d;if(holiday)multiplier*=r.getHolidayMultiplier();if(inventory<=r.getLowInventoryThreshold())multiplier*=r.getAvailabilityMultiplier();if(demand>=r.getDemandBookingsThreshold())multiplier*=r.getDemandMultiplier();if(days>=0&&days<=2)multiplier*=r.getLeadTimeMultiplier();return multiplier;}
 private PriceHistory store(String type,String id,double base,double multiplier,List<String> reasons){PriceHistory p=new PriceHistory();p.setItemType(type);p.setItemId(id);p.setBasePrice(base);p.setMultiplier(multiplier);p.setCurrentPrice(Math.round(base*multiplier*100d)/100d);p.setReason(reasons.isEmpty()?"BASE_PRICE":String.join(",",reasons));return history.save(p);}
}
